// Type: Owner.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Owner {
    Jig,
    Family(Family),
}

// Record: Owner.
impl Owner {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Named("Family"),
        skein_codec::bounds::Node::Enum { variants: &[0, 1] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 3;
}

impl Record for Owner {
    type Limits = Limits;
    const TAIL: Path = paths::OWNER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "Owner")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "Owner")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Jig => field::put(out, &[0], paths::OWNER_TAG),
            Self::Family(value) => { field::put(out, &[1], paths::OWNER_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OWNER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Jig),
            1 => Ok(Self::Family(Family::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::OWNER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

