// Type: AnswerOn.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum AnswerOn {
    Question(AnswerQuestion),
    Person(AnswerPerson),
}

// Record: AnswerOn.
impl AnswerOn {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Named("AnswerQuestion"),
        skein_codec::bounds::Node::Named("AnswerPerson"),
        skein_codec::bounds::Node::Enum { variants: &[0, 1] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 27;
}

impl Record for AnswerOn {
    type Limits = Limits;
    const TAIL: Path = paths::ANSWER_ON_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "AnswerOn")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "AnswerOn")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Question(value) => { field::put(out, &[0], paths::ANSWER_ON_TAG)?; value.write(limits, out) },
            Self::Person(value) => { field::put(out, &[1], paths::ANSWER_ON_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ANSWER_ON_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Question(AnswerQuestion::read(limits, reader)?)),
            1 => Ok(Self::Person(AnswerPerson::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::ANSWER_ON_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

