// Record: HistoryRow.
impl HistoryRow {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Named("HistoryRowChange"),
        skein_codec::bounds::Node::Boxed { item: 0, size: size_of::<HistoryRowChange>() },
        skein_codec::bounds::Node::Named("HistoryRowAttempt"),
        skein_codec::bounds::Node::Named("HistoryRowHold"),
        skein_codec::bounds::Node::Enum { variants: &[1, 2, 3] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 532;
}

impl Record for HistoryRow {
    type Limits = Limits;
    const TAIL: Path = paths::HISTORY_ROW_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "HistoryRow")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "HistoryRow")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Change(value) => { field::put(out, &[0], paths::HISTORY_ROW_TAG)?; value.write(limits, out) },
            Self::Attempt(value) => { field::put(out, &[1], paths::HISTORY_ROW_TAG)?; value.write(limits, out) },
            Self::Hold(value) => { field::put(out, &[2], paths::HISTORY_ROW_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::HISTORY_ROW_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Change(Box::new(HistoryRowChange::read(limits, reader)?))),
            1 => Ok(Self::Attempt(HistoryRowAttempt::read(limits, reader)?)),
            2 => Ok(Self::Hold(HistoryRowHold::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::HISTORY_ROW_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

